'use client';

import {useEffect,useRef,useState,type FormEvent,type ReactNode} from 'react';
import Link from 'next/link';
import {usePathname} from 'next/navigation';
import {Activity,ArrowDownToLine,ArrowLeft,ArrowRight,ArrowUpRight,AudioLines,Bell,Check,CheckCheck,ChevronDown,ChevronLeft,ChevronRight,Clock3,Copy,Expand,ExternalLink,FileCheck2,Flag,Gamepad2,Goal,LayoutDashboard,LayoutGrid,ListFilter,Menu,Monitor,MoreHorizontal,Pause,Pencil,Play,Plus,Radio,RotateCcw,Search,Settings,Shield,Shuffle,Sparkles,Square,Target,Trash2,Trophy,Upload,UserCheck,UserPlus,Users,Video,Wifi,X,type LucideIcon} from 'lucide-react';
import {clock,initialState,makeDraw,playerById,standing,STORAGE_KEY,type ArenaState,type Match,type Player} from '../lib/model';
import {CrownBrand,ReferenceRegistration,ReferenceStandings,ReferenceCompetition,ReferencePlayers,ReferenceFixtures,ReferenceMatchControl,ReferenceAdmin,ReferenceLive} from './reference-pages';
import { ReferenceHome } from './reference-home';
import { registrationApi } from '../lib/registration-api';

type Action=(s:ArenaState)=>ArenaState;
type AppContext={state:ArenaState;update:(fn:Action,message?:string)=>void;notify:(msg:string)=>void;now:number;openMatch:(id:string)=>void};
type RegistrationContext=AppContext&{query:string;setQuery:(value:string)=>void};

function SharedRegistrations(c:RegistrationContext){
 const [key,setKey]=useState('');
 const [activeKey,setActiveKey]=useState('');
 const [players,setPlayers]=useState<Player[]>([]);
 const [busy,setBusy]=useState(false);
 const [error,setError]=useState('');
 const headers=(token:string)=>({Authorization:`Bearer ${token}`});
 async function load(token:string){
  setBusy(true);setError('');
  try{setPlayers(await registrationApi<Player[]>('admin/registrations',{headers:headers(token)}));setActiveKey(token);setKey('')}
  catch(e){setError(e instanceof Error?e.message:'Não foi possível carregar as inscrições.')}
  finally{setBusy(false)}
 }
 async function onReview(id:string,status:Player['status']){
  await registrationApi('admin/registrations/'+encodeURIComponent(id),{
   method:'PATCH',headers:{...headers(activeKey),'Content-Type':'application/json'},body:JSON.stringify({status})
  });
  setPlayers(rows=>rows.map(player=>player.id===id?{...player,status}:player));
  c.notify(status==='approved'?'Inscrição aprovada.':'Inscrição rejeitada.');
 }
 return <>
  <div className="panel list-toolbar">
   {activeKey?<><Button disabled={busy} onClick={()=>void load(activeKey)}>Atualizar inscrições</Button><Button disabled={busy} onClick={()=>{setActiveKey('');setPlayers([]);setError('')}}>Bloquear acesso</Button></>:
   <form className="list-toolbar" onSubmit={e=>{e.preventDefault();void load(key)}}>
    <label className="field">Chave da organização<input type="password" required value={key} onChange={e=>setKey(e.target.value)} /></label>
    <Button type="submit" disabled={busy}>{busy?'Carregando…':'Acessar inscrições'}</Button>
   </form>}
   {error&&<p role="alert">{error}</p>}
  </div>
  {activeKey&&<Registrations {...c} state={{...c.state,players}} onReview={onReview}/>}
 </>;
}
const nav=[{path:'/admin',label:'Dashboard',icon:LayoutDashboard},{path:'/inscricoes',label:'Inscrições',icon:FileCheck2},{path:'/jogadores',label:'Jogadores',icon:Users},{path:'/sorteio',label:'Sorteio',icon:Shuffle},{path:'/partidas',label:'Partidas',icon:Gamepad2},{path:'/grupos',label:'Grupos e classificação',icon:LayoutGrid},{path:'/rankings',label:'Rankings e prêmios',icon:Trophy}];
const labels:Record<string,string>={'/admin':'Painel do Administrador','/inscricoes':'Inscrições','/jogadores':'Jogadores','/sorteio':'Sorteio','/partidas':'Partidas','/grupos':'Grupos e classificação','/rankings':'Rankings e prêmios','/telao':'Arena Marks Live','/broadcast':'Transmissão','/configuracoes':'Configurações'};
function Button({children,onClick,kind='',className='',disabled=false,type='button',title}:{children:ReactNode;onClick?:()=>void;kind?:string;className?:string;disabled?:boolean;type?:'button'|'submit';title?:string}){return <button type={type} title={title} disabled={disabled} onClick={onClick} className={`button ${kind} ${className}`}>{children}</button>}
function Pill({children,tone=''}:{children:ReactNode;tone?:string}){return <span className={`pill ${tone}`}>{children}</span>}
function Avatar({player,size=''}:{player?:Player;size?:string}){return <span className={`avatar ${size}`} style={{'--avatar-color':player?.color||'#8ccda2'} as React.CSSProperties}>{player?.photo?<img src={player.photo} alt={player.name}/>:player?.name.split(' ').slice(0,2).map(n=>n[0]).join('')||'?'}</span>}
function Club({player,large=false}:{player?:Player;large?:boolean}){return <span className={`club ${large?'large':''}`} style={{'--club-color':player?.color||'#ccc'} as React.CSSProperties}><Shield strokeWidth={1.6}/><b>{player?.club.split(' ').filter(n=>!['de','da'].includes(n)).map(n=>n[0]).slice(0,3).join('')||'CML'}</b></span>}
function Empty({title,detail}:{title:string;detail:string}){return <div className="empty"><Search size={26}/><h3>{title}</h3><p>{detail}</p></div>}
function SectionTitle({title,note,action}:{title:string;note?:string;action?:ReactNode}){return <div className="section-title"><div><h2>{title}</h2>{note&&<p>{note}</p>}</div>{action}</div>}
function Heading({eyebrow='CHAMPIONS MARKS LEAGUE II',title,description,children}:{eyebrow?:string;title:string;description:string;children?:ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div><div className="heading-actions">{children}</div></div>}
function Modal({title,onClose,children,wide=false}:{title:string;onClose:()=>void;children:ReactNode;wide?:boolean}){const ref=useRef<HTMLDivElement>(null);const closeRef=useRef(onClose);closeRef.current=onClose;useEffect(()=>{const before=document.activeElement as HTMLElement|null;const bodyOverflow=document.body.style.overflow;document.body.style.overflow='hidden';const first=()=>ref.current?.querySelector<HTMLElement>('button,input,select,a')?.focus();first();const key=(e:KeyboardEvent)=>{if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const items=ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select,textarea,a[href]');if(!items?.length)return;const a=items[0],b=items[items.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus()}}};document.addEventListener('keydown',key);return()=>{document.body.style.overflow=bodyOverflow;document.removeEventListener('keydown',key);before?.focus()}},[]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div ref={ref} role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide?'wide':''}`}><div className="modal-title"><h2>{title}</h2><button className="icon-button" onClick={onClose} title="Fechar"><X size={20}/></button></div>{children}</div></div>}

export default function ArenaApp(){
 const pathname=usePathname()||'/';const [state,setState]=useState<ArenaState>(initialState);const [ready,setReady]=useState(false);const [now,setNow]=useState(0);const [toast,setToast]=useState('');const [sidebar,setSidebar]=useState(false);const [matchId,setMatchId]=useState<string|null>(null);const [playerEdit,setPlayerEdit]=useState<Player|'new'|null>(null);const [notifications,setNotifications]=useState(false);const [query,setQuery]=useState('');const [storageError,setStorageError]=useState(false);const channel=useRef<BroadcastChannel|null>(null);const stateRef=useRef(state);stateRef.current=state;
 useEffect(()=>{try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){const data=JSON.parse(raw);if(data.settings&&Array.isArray(data.players)&&Array.isArray(data.matches)){const settings=data.settings;if(settings.capacity===25&&settings.groupCount===5&&settings.stationCount===3){data.settings={...settings,capacity:32,groupCount:4,stationCount:6};localStorage.setItem(STORAGE_KEY,JSON.stringify(data))}setState(data)}}else{localStorage.setItem(STORAGE_KEY,JSON.stringify(stateRef.current))}}catch{setStorageError(true)}setReady(true);setNow(Date.now());const timer=setInterval(()=>setNow(Date.now()),1000);const receive=(event:StorageEvent)=>{if(event.key===STORAGE_KEY&&event.newValue)try{setState(JSON.parse(event.newValue))}catch{}};window.addEventListener('storage',receive);if('BroadcastChannel'in window){channel.current=new BroadcastChannel(STORAGE_KEY);channel.current.onmessage=e=>{if(e.data?.settings)setState(e.data)}}return()=>{clearInterval(timer);window.removeEventListener('storage',receive);channel.current?.close()}},[]);
 useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(id)},[toast]);
 useEffect(()=>{setSidebar(false);setNotifications(false)},[pathname]);
 function update(fn:Action,message?:string){let next=fn(stateRef.current);if(message)next={...next,audit:[{id:crypto.randomUUID(),text:message,at:new Date().toISOString()},...next.audit].slice(0,60)};stateRef.current=next;setState(next);try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));setStorageError(false)}catch{setStorageError(true)}channel.current?.postMessage(next);if(message)setToast(message)}
 const context:AppContext={state,update,notify:setToast,now,openMatch:setMatchId};const pending=state.players.filter(p=>p.status==='pending').length;
 const referencePage=pathname==='/'||pathname==='/portal'?<ReferenceHome {...context}/>:pathname==='/inscricao'||pathname==='/inscrever'?<ReferenceRegistration {...context}/>:pathname==='/classificacao'?<ReferenceStandings {...context}/>:pathname==='/campeonato'?<ReferenceHome {...context} view="competition"/>:pathname==='/regulamento'?<ReferenceHome {...context} view="rules"/>:pathname==='/atletas'?<ReferencePlayers {...context}/>:pathname==='/jogos'?<ReferenceFixtures {...context}/>:pathname==='/controle-da-partida'?<ReferenceMatchControl {...context}/>:null;const livePage=pathname==='/live'||pathname.startsWith('/overlay');
 if(!ready)return <div className="loading"><img src="/arena-marks.png" alt="Arena Marks"/><span>Preparando a arena…</span></div>;
 return <>{referencePage?referencePage:livePage?<LiveScreen {...context} overlay={pathname.startsWith('/overlay')}/>:<div className="app-shell">
 {sidebar&&<div className="sidebar-backdrop" onClick={()=>setSidebar(false)}/>}
 <aside className={`sidebar ${sidebar?'visible':''}`}><Link className="brand" href="/admin"><CrownBrand/></Link><div className="edition-switch"><span className="edition-mark"><Trophy size={18}/></span><div><strong>Champions Marks League</strong><small>II edição <span>•</span> 2026</small></div><ChevronDown size={14}/></div><div className="nav-label">CAMPEONATO</div><nav>{nav.map(n=><Link key={n.path} href={n.path} className={`nav-link ${pathname===n.path?'active':''}`}><n.icon size={18}/><span>{n.label}</span>{n.path==='/inscricoes'&&pending>0&&<em>{pending}</em>}</Link>)}</nav><div className="nav-label">AO VIVO</div><nav><Link className="nav-link" href="/controle-da-partida"><Gamepad2 size={18}/><span>Controle da partida</span></Link><Link className={`nav-link ${pathname==='/telao'?'active':''}`} href="/telao"><Monitor size={18}/><span>Arena Marks Live</span><i className="online-dot"/></Link><Link className={`nav-link ${pathname==='/broadcast'?'active':''}`} href="/broadcast"><Radio size={18}/><span>Transmissão</span></Link></nav><div className="sidebar-bottom"><Link href="/" target="_blank" className="portal-link"><ExternalLink size={16}/>Portal do campeonato<ArrowUpRight size={15}/></Link><Link href="/configuracoes" className={`nav-link ${pathname==='/configuracoes'?'active':''}`}><Settings size={18}/>Configurações</Link><div className="user-profile"><span className="user-avatar">AM</span><div><strong>Organização Arena Marks</strong><small>Ambiente de demonstração</small></div><MoreHorizontal size={17}/></div></div></aside>
 <div className="workspace"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" onClick={()=>setSidebar(!sidebar)} title="Abrir menu"><Menu/></button><span>Workspace</span><ChevronRight size={13}/><b>{labels[pathname]||'Arena Marks'}</b></div><div className="topbar-right"><span className="demo-indicator"><span/>Prévia V1</span><div className="notification-wrap"><button className="icon-button notification-button" title="Notificações" onClick={()=>setNotifications(!notifications)}><Bell size={18}/>{pending>0&&<i/>}</button>{notifications&&<div className="notification-popover"><strong>Central de notificações</strong><Link href="/inscricoes"><UserPlus size={18}/><span>{pending} inscrições aguardam análise<small>Revisar participantes</small></span><ArrowRight size={15}/></Link>{state.audit.slice(0,2).map(a=><p key={a.id}>{a.text}</p>)}</div>}</div><span className="topbar-divider"/><span className="user-avatar small">AM</span></div></header>
 <main className="main-content">{pathname==='/admin'?<ReferenceAdmin {...context}/>:pathname==='/inscricoes'?<SharedRegistrations {...context} query={query} setQuery={setQuery}/>:pathname==='/jogadores'?<Players {...context} query={query} setQuery={setQuery} edit={setPlayerEdit}/>:pathname==='/sorteio'?<DrawPage {...context}/>:pathname==='/partidas'?<Matches {...context}/>:pathname==='/grupos'?<Groups {...context}/>:pathname==='/rankings'?<Rankings {...context}/>:pathname==='/telao'?<LiveControl {...context}/>:pathname==='/broadcast'?<Broadcast {...context}/>:pathname==='/configuracoes'?<SettingsPage {...context}/>:<Empty title="Página não encontrada" detail="Selecione uma seção no menu da Arena Marks."/>}
 <footer className="app-footer"><span>ARENA MARKS <b>·</b> A nossa resenha. A nossa liga.</span><span><i className="online-dot"/>Dados de demonstração <span className="footer-divider">/</span> Versão 0.1</span></footer></main></div></div>}
 {matchId&&<MatchOperator {...context} matchId={matchId} onClose={()=>setMatchId(null)}/>}{playerEdit&&<PlayerEditor {...context} player={playerEdit} onClose={()=>setPlayerEdit(null)}/>}{toast&&<div role="status" className="toast"><CheckCheck size={18}/><span>{toast}</span><button title="Fechar aviso" onClick={()=>setToast('')}><X size={16}/></button></div>}{storageError&&<div className="storage-warning" role="alert">Não foi possível salvar no navegador. As alterações desta sessão podem ser perdidas.</div>}
 </>;
}

function Dashboard(c:AppContext){const {state}=c;const approved=state.players.filter(p=>p.status==='approved').length;const pending=state.players.filter(p=>p.status==='pending');const live=state.matches.filter(m=>['live','paused'].includes(m.status));const next=state.matches.filter(m=>m.status==='scheduled');return <>
 <Heading title="A arena está pronta. Vamos jogar?" description="Tudo o que acontece no campeonato, em um só lugar."><Link className="button" href="/portal" target="_blank"><ExternalLink size={15}/>Ver portal</Link><Link className="button primary" href="/telao"><Monitor size={16}/>Abrir Arena Live<ArrowUpRight size={15}/></Link></Heading>
 <div className="edition-band"><span className="edition-cup"><Trophy size={24}/></span><div className="edition-band-copy"><div className="eyebrow">O NOSSO PRÓXIMO CAPÍTULO</div><h2>{state.settings.title}<span>II</span></h2><div><span><Gamepad2 size={13}/>{state.settings.game}</span><i/><span>Fase de grupos</span><i/><span>Data a definir</span></div></div><div className="edition-band-right"><Pill tone="green"><span className="online-dot"/>Edição de demonstração</Pill><Link href="/configuracoes" title="Configurar edição"><Settings size={18}/></Link></div></div>
 <div className="stats-grid"><Stat label="Jogadores inscritos" value={state.players.length} unit={`/ ${state.settings.capacity}`} icon={Users} note={`${approved} aprovados para a competição`} trend="Inscrições abertas"/><Stat label="Inscrições pendentes" value={pending.length} icon={FileCheck2} note="Aguardando sua aprovação" trend="Revisar inscrições" href="/inscricoes" tone="amber"/><Stat label="Partidas ao vivo" value={live.length} icon={Gamepad2} note={`de ${state.settings.stationCount} estações disponíveis`} trend="Arena em movimento" tone="mint"/><Stat label="Partidas confirmadas" value={state.matches.filter(m=>m.status==='confirmed').length} icon={Flag} note="Resultados oficiais da edição" trend="Ver resultados" href="/partidas" tone="blue"/></div>
 <div className="dashboard-main"><section className="dashboard-live"><SectionTitle title="Dentro de campo" action={<Link className="text-link" href="/partidas">Todas as partidas<ArrowUpRight size={14}/></Link>}/><div className="match-grid">{live.length?live.slice(0,2).map(m=><MatchCard key={m.id} {...c} match={m}/>):<Empty title="A bola ainda não rolou" detail="Inicie uma partida para acompanhar a arena."/>}</div></section><section className="upcoming"><SectionTitle title="Próximos jogos" action={<span className="tiny-count">{next.length}</span>}/><div className="upcoming-list">{next.slice(0,3).map(m=><button className="upcoming-item" key={m.id} onClick={()=>c.openMatch(m.id)}><div className="upcoming-time"><Clock3 size={12}/>{m.time}<small>{m.station}</small></div><div className="upcoming-players"><span>{playerById(state,m.home)?.nickname}<small>vs</small>{playerById(state,m.away)?.nickname}</span><small>Grupo {m.group} <span>·</span> Fase de grupos</small></div><ChevronRight size={15}/></button>)}</div></section></div>
 <div className="dashboard-lower"><section className="panel standings-panel"><SectionTitle title="A disputa pela liderança" note="Classificação oficial · Grupo A" action={<Link className="text-link" href="/grupos">Ver grupos<ArrowUpRight size={14}/></Link>}/><StandingsTable {...c} group="A" compact/><div className="panel-foot"><span className="qualification-dot"/>Classificação provisória, conforme resultados confirmados</div></section><section className="panel pending-panel"><SectionTitle title="De olho nas inscrições" note={`${pending.length} jogadores esperando entrar em campo`} action={<span className="pill amber">Pendente</span>}/>{pending.slice(0,3).map(p=><div className="pending-row" key={p.id}><Avatar player={p}/><div><strong>{p.name}</strong><small>Aguardando análise</small></div><button className="icon-button approve-button" title={`Aprovar ${p.name}`} onClick={()=>c.update(s=>({...s,players:s.players.map(x=>x.id===p.id?{...x,status:'approved'}:x)}),`${p.name} aprovado. Apto para o sorteio.`)}><Check size={17}/></button></div>)}{!pending.length&&<div className="all-clear"><CheckCheck/>Todas as inscrições foram analisadas.</div>}<Link className="pending-footer" href="/inscricoes">Gerenciar inscrições<ArrowRight size={14}/></Link></section></div>
 <div className="activity-strip"><span><Activity size={15}/>Última movimentação</span><p>{state.audit[0]?.text||'Nenhuma movimentação registrada.'}</p><span>Agora há pouco</span></div>
 </>}
function Stat({label,value,unit,icon:Icon,note,trend,href,tone=''}:{label:string;value:number;unit?:string;icon:LucideIcon;note:string;trend:string;href?:string;tone?:string}){return <article className={`stat ${tone}`}><div className="stat-title">{label}<span><Icon size={17}/></span></div><div className="stat-number">{value.toString().padStart(2,'0')}<small>{unit}</small></div><p>{note}</p>{href?<Link href={href} className="stat-foot">{trend}<ArrowUpRight size={13}/></Link>:<span className="stat-foot"><span className="online-dot"/>{trend}</span>}</article>}
function MatchCard({match,...c}:AppContext&{match:Match}){const home=playerById(c.state,match.home),away=playerById(c.state,match.away);return <article className="match-card"><div className="match-card-top"><Pill tone="green"><i className="online-dot"/>{match.status==='paused'?'Pausado':'Ao vivo'}</Pill><span>Grupo {match.group}<b>·</b>{match.station}</span><MoreHorizontal size={17}/></div><div className="match-duel"><div className="match-person"><Club player={home} large/><strong>{home?.nickname}</strong><small>{home?.club}</small></div><div className="match-score"><strong>{match.homeScore}<span>:</span>{match.awayScore}</strong><span><Clock3 size={11}/>{clock(match,c.now)}</span></div><div className="match-person"><Club player={away} large/><strong>{away?.nickname}</strong><small>{away?.club}</small></div></div><div className="match-card-footer"><span><span className="online-dot"/>Fase de grupos</span><button onClick={()=>c.openMatch(match.id)}>Operar partida<ArrowRight size={13}/></button></div></article>}
function StandingsTable({group,compact=false,...c}:AppContext&{group:string;compact?:boolean}){const rows=standing(c.state,group);return <div className="table-scroll"><table className="standings-table"><thead><tr><th className="rank-cell">#</th><th>JOGADOR</th><th>PTS</th><th>J</th><th>V</th>{!compact&&<><th>E</th><th>D</th><th>GP</th><th>GC</th></>}<th>SG</th>{compact&&<th>FORMA</th>}</tr></thead><tbody>{rows.map((p,i)=><tr key={p.id}><td className="rank-cell"><span className={i<2?'qualifies':''}>{i+1}</span></td><td><div className="table-player"><Avatar player={p} size="mini"/><span><strong>{p.name}</strong><small>{p.club}</small></span></div></td><td className="points">{p.points}</td><td>{p.played}</td><td>{p.wins}</td>{!compact&&<><td>{p.draws}</td><td>{p.losses}</td><td>{p.gf}</td><td>{p.ga}</td></>}<td className={p.gd>0?'positive':''}>{p.gd>0?'+':''}{p.gd}</td>{compact&&<td><div className="form-dots">{p.played?<><span className={p.wins?'win':'loss'}>{p.wins?'V':'D'}</span><span>–</span><span>–</span></>:<><span>–</span><span>–</span><span>–</span></>}</div></td>}</tr>)}</tbody></table>{!rows.length&&<Empty title="Grupo sem participantes" detail="Os participantes aparecerão após o sorteio."/>}</div>}

function Registrations(c:AppContext&{query:string;setQuery:(s:string)=>void;onReview:(id:string,status:Player['status'])=>Promise<void>}){const [filter,setFilter]=useState('pending');const [review,setReview]=useState<Player|null>(null);const rows=c.state.players.filter(p=>(filter==='all'||p.status===filter)&&`${p.name} ${p.nickname}`.toLowerCase().includes(c.query.toLowerCase()));const [saving,setSaving]=useState(false);const [reviewError,setReviewError]=useState('');async function reviewPlayer(p:Player,status:Player['status']){setSaving(true);setReviewError('');try{await c.onReview(p.id,status);setReview(null)}catch(e){setReviewError(e instanceof Error?e.message:'Falha ao salvar.')}finally{setSaving(false)}}return <><Heading title="Todo grande jogo começa aqui." description="Analise os inscritos e receba os próximos protagonistas da liga."><Link href="/inscrever" target="_blank" className="button primary"><UserPlus size={16}/>Abrir inscrição<ArrowUpRight size={15}/></Link></Heading><div className="summary-ribbon"><span><b>{c.state.players.length}</b> inscrições recebidas</span><span><i className="online-dot"/><b>{c.state.players.filter(p=>p.status==='approved').length}</b> aprovadas</span><span className="amber-text"><Clock3 size={15}/><b>{c.state.players.filter(p=>p.status==='pending').length}</b> em análise</span></div><div className="panel"><div className="list-toolbar"><div className="tabs">{[['pending','Em análise'],['approved','Aprovadas'],['rejected','Rejeitadas'],['all','Todas']].map(([v,l])=><button key={v} className={filter===v?'selected':''} onClick={()=>setFilter(v)}>{l}</button>)}</div><SearchInput value={c.query} onChange={c.setQuery} placeholder="Buscar inscrição…"/></div><div className="table-scroll"><table><thead><tr><th>PARTICIPANTE</th><th>APELIDO</th><th>SITUAÇÃO</th><th>PRÓXIMA ETAPA</th><th className="right">AÇÕES</th></tr></thead><tbody>{rows.map(p=><tr key={p.id}><td><div className="table-player"><Avatar player={p}/><strong>{p.name}</strong></div></td><td>{p.nickname}</td><td><Pill tone={p.status==='approved'?'green':p.status==='pending'?'amber':'red'}>{p.status==='approved'?'Aprovada':p.status==='pending'?'Em análise':'Rejeitada'}</Pill></td><td>{p.status==='approved'?p.group?'Grupo '+p.group:'Apta ao sorteio':p.status==='pending'?'Revisão da organização':'Inscrição encerrada'}</td><td className="right"><Button onClick={()=>{setReviewError('');setReview(p)}}>Revisar<ArrowUpRight size={14}/></Button></td></tr>)}</tbody></table>{!rows.length&&<Empty title="Nenhuma inscrição por aqui" detail="Altere a busca ou selecione outra situação."/>}</div><div className="panel-foot">{rows.length} inscrições nesta visualização</div></div>{review&&<Modal title="Revisar inscrição" onClose={()=>{if(!saving)setReview(null)}}><div className="review-profile"><Avatar player={review} size="big"/><h3>{review.name}</h3><p>{review.nickname}</p><Pill tone="amber">{review.status==='pending'?'Aguardando análise':'Inscrição analisada'}</Pill></div><dl className="detail-grid"><div><dt>Contato</dt><dd>{review.contact||'Não informado nesta demonstração'}</dd></div><div><dt>Foto</dt><dd>{review.photo?'Foto enviada':'Foto não enviada'}</dd></div><div><dt>Edição</dt><dd>{c.state.settings.title}</dd></div></dl>{reviewError&&<p role="alert">{reviewError}</p>}<div className="modal-actions"><Button disabled={saving} kind="danger" onClick={()=>reviewPlayer(review,'rejected')}>Rejeitar inscrição</Button><Button disabled={saving} kind="primary" onClick={()=>reviewPlayer(review,'approved')}><UserCheck size={16}/>Aprovar inscrição</Button></div></Modal>}</>}
function SearchInput({value,onChange,placeholder}:{value:string;onChange:(v:string)=>void;placeholder:string}){return <label className="search-input"><Search size={16}/><input aria-label={placeholder} placeholder={placeholder} value={value} onChange={e=>onChange(e.target.value)}/>{value&&<button title="Limpar busca" onClick={()=>onChange('')}><X size={14}/></button>}</label>}
function Players(c:AppContext&{query:string;setQuery:(s:string)=>void;edit:(p:Player|'new')=>void}){const [group,setGroup]=useState('all');const rows=c.state.players.filter(p=>p.status==='approved'&&(group==='all'||p.group===group)&&`${p.name} ${p.club}`.toLowerCase().includes(c.query.toLowerCase()));return <><Heading title="Os protagonistas da nossa liga." description="Pessoas, clubes e histórias que fazem a Arena Marks."><Button kind="primary" onClick={()=>c.edit('new')}><Plus size={16}/>Adicionar jogador</Button></Heading><div className="list-toolbar unframed"><div className="segmented"><button className={group==='all'?'selected':''} onClick={()=>setGroup('all')}>Todos</button>{['A','B','C','D','E'].map(g=><button className={group===g?'selected':''} key={g} onClick={()=>setGroup(g)}>Grupo {g}</button>)}</div><SearchInput value={c.query} onChange={c.setQuery} placeholder="Buscar jogador ou clube…"/></div><div className="players-grid">{rows.map(p=><article className="player-card" key={p.id}><div className="player-card-cover" style={{'--player-color':p.color} as React.CSSProperties}><span>CHAMPIONS MARKS LEAGUE</span><Club player={p}/></div><div className="player-card-body"><Avatar player={p} size="big"/><button className="icon-button edit-player" title={`Editar ${p.name}`} onClick={()=>c.edit(p)}><Pencil size={16}/></button><h3>{p.name}</h3><p>{p.club||'Clube a definir'}</p><div><Pill tone={p.group?'green':''}>{p.group?'Grupo '+p.group:'Apto ao sorteio'}</Pill><span>II edição</span></div></div></article>)}</div>{!rows.length&&<Empty title="Nenhum jogador encontrado" detail="Tente outro nome ou grupo."/>}</>}
function PlayerEditor(c:AppContext&{player:Player|'new';onClose:()=>void}){const p=c.player;const [name,setName]=useState(p==='new'?'':p.name);const [nickname,setNickname]=useState(p==='new'?'':p.nickname);const [club,setClub]=useState(p==='new'?'':p.club);const [photo,setPhoto]=useState(p==='new'?'':p.photo);const [error,setError]=useState('');return <Modal title={p==='new'?'Novo jogador':'Editar jogador'} onClose={c.onClose}><form onSubmit={e=>{e.preventDefault();if(!name.trim())return;if(p==='new'&&c.state.players.filter(x=>x.status!=='rejected').length>=c.state.settings.capacity){setError('A edição atingiu o limite de vagas. Ajuste a capacidade nas configurações.');return}c.update(s=>({...s,players:p==='new'?[...s.players,{id:crypto.randomUUID(),name:name.trim(),nickname:nickname.trim()||name.split(' ')[0],club:club.trim(),photo,color:'#9dda99',status:'approved',group:'',contact:''}]:s.players.map(x=>x.id===p.id?{...x,name:name.trim(),nickname:nickname.trim(),club:club.trim(),photo}:x)}),`${name.trim()}: cadastro salvo.`);c.onClose()}}><div className="form-grid"><label className="field full">Nome completo<input required maxLength={80} value={name} onChange={e=>setName(e.target.value)}/></label><label className="field">Apelido<input maxLength={30} value={nickname} onChange={e=>setNickname(e.target.value)}/></label><label className="field">Clube virtual<input maxLength={60} value={club} onChange={e=>setClub(e.target.value)}/></label><ImageUpload value={photo} onChange={setPhoto} onError={setError}/></div>{error&&<p className="form-error">{error}</p>}<div className="modal-actions"><Button onClick={c.onClose}>Cancelar</Button><Button type="submit" kind="primary"><Check size={16}/>Salvar jogador</Button></div></form></Modal>}
function ImageUpload({value,onChange,onError}:{value:string;onChange:(v:string)=>void;onError:(v:string)=>void}){return <div className="field full"><span>Foto do participante</span><label className="upload-field">{value?<img src={value} alt="Prévia da foto"/>:<Upload size={25}/>}<span><strong>{value?'Trocar fotografia':'Selecionar fotografia'}</strong><small>JPG, PNG ou WebP · até 2 MB nesta prévia</small></span><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>{const f=e.target.files?.[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>2*1024*1024){onError('Use uma imagem JPG, PNG ou WebP de até 2 MB.');return}const reader=new FileReader();reader.onload=()=>{onChange(String(reader.result));onError('')};reader.onerror=()=>onError('Não foi possível ler a imagem.');reader.readAsDataURL(f)}}/></label>{value&&<button type="button" className="text-link" onClick={()=>onChange('')}>Remover foto</button>}</div>}

function DrawPage(c:AppContext){const [seed,setSeed]=useState('CML-II-2026');const [mode,setMode]=useState('random');const [draft,setDraft]=useState(c.state.draw);const eligible=c.state.players.filter(p=>p.status==='approved');const [confirm,setConfirm]=useState(false);return <><Heading title="O destino também entra em campo." description="Confira os elegíveis, simule os grupos e revise antes de publicar."><Pill tone="green"><UserCheck size={13}/>{eligible.length} jogadores elegíveis</Pill></Heading><div className="draw-layout"><section className="panel draw-config"><SectionTitle title="Configurar sorteio" note="Grupos da fase inicial"/><label className="field">Modo de distribuição<select value={mode} onChange={e=>setMode(e.target.value)}><option value="random">Aleatório</option><option value="pots">Distribuição em serpentina</option></select></label><label className="field">Chave do sorteio<input value={seed} onChange={e=>setSeed(e.target.value)} maxLength={100}/></label><div className="draw-summary"><span>Grupos<strong>{c.state.settings.groupCount}</strong></span><span>Jogadores<strong>{eligible.length}</strong></span><span>Pendentes<strong>{c.state.players.filter(p=>p.status==='pending').length}</strong></span></div><Button className="full-width" kind="primary" disabled={!seed.trim()||eligible.length<c.state.settings.groupCount} onClick={()=>{setDraft({seed,mode,groups:makeDraw(c.state.players,c.state.settings.groupCount,seed,mode),published:false,createdAt:new Date().toISOString()});c.notify('Simulação criada. Revise a composição dos grupos.')}}><Shuffle size={16}/>Simular sorteio</Button><div className="context-note"><Shield size={17}/><p>Somente participantes aprovados entram no sorteio oficial.</p></div>{mode==='pots'&&<p className="muted small-text">A serpentina distribui posições; balanceamento por habilidade depende dos ratings da próxima etapa.</p>}</section><section><SectionTitle title={draft?'Prévia dos grupos':'Os próximos confrontos começam aqui'} note={draft?`Chave ${draft.seed} · ${draft.published?'Publicado':'Simulação não publicada'}`:'A composição será exibida após a simulação.'} action={draft&&<Button disabled={draft.published} onClick={()=>setConfirm(true)}><CheckCheck size={15}/>{draft.published?'Publicado':'Publicar grupos'}</Button>}/>{draft?<div className="draw-groups">{draft.groups.map((ids,i)=><article className="panel draw-group" key={i}><div className="group-title"><span>{String.fromCharCode(65+i)}</span><h3>Grupo {String.fromCharCode(65+i)}</h3><small>{ids.length} jogadores</small></div>{ids.map(id=><div className="draw-member" key={id}><Avatar player={playerById(c.state,id)} size="mini"/><strong>{playerById(c.state,id)?.name}</strong></div>)}</article>)}</div>:<div className="draw-empty"><Shuffle size={48}/><h3>Um novo capítulo para cada jogador.</h3><p>O próximo adversário pode ser seu melhor amigo.</p><div className="draw-empty-letters">{'ABCDE'.split('').map(l=><span key={l}>{l}</span>)}</div></div>}</section></div>{confirm&&<Modal title="Publicar composição dos grupos" onClose={()=>setConfirm(false)}><p className="dialog-copy">A publicação substitui os grupos desta edição. Partidas em andamento ou já realizadas impedem essa alteração.</p><div className="context-note amber-note"><Shield size={18}/><p>Esta edição de demonstração já possui partidas. Você pode testar a simulação; a publicação está bloqueada para preservar os resultados.</p></div><div className="modal-actions"><Button onClick={()=>setConfirm(false)}>Voltar à simulação</Button><Button kind="primary" disabled={c.state.matches.some(m=>m.status!=='scheduled')} onClick={()=>{if(!draft)return;c.update(s=>({...s,draw:{...draft,published:true},players:s.players.map(p=>({...p,group:draft.groups.findIndex(g=>g.includes(p.id))<0?'':String.fromCharCode(65+draft.groups.findIndex(g=>g.includes(p.id)))}))}),'Sorteio publicado.');setDraft({...draft,published:true});setConfirm(false)}}>Confirmar publicação</Button></div></Modal>}</>}

function Matches(c:AppContext){const [filter,setFilter]=useState('all');const rows=c.state.matches.filter(m=>filter==='all'||filter==='live'&&['live','paused'].includes(m.status)||filter==='results'&&['finished','confirmed'].includes(m.status)||m.status===filter);return <><Heading title="Cada partida tem uma história." description="Organize as estações, opere os jogos e confirme os resultados."><Link href="/telao" className="button primary"><Monitor size={16}/>Controle do Telão</Link></Heading><div className="list-toolbar unframed"><div className="tabs">{[['all','Todas'],['live','Ao vivo'],['scheduled','Agendadas'],['results','Resultados']].map(([v,l])=><button className={filter===v?'selected':''} onClick={()=>setFilter(v)} key={v}>{l}{v==='live'&&<i className="online-dot"/>}</button>)}</div><span className="muted small-text"><Gamepad2 size={14}/>{c.state.settings.stationCount} estações nesta edição</span></div><div className="panel"><div className="table-scroll"><table><thead><tr><th>CONFRONTO</th><th>GRUPO</th><th>ESTAÇÃO</th><th>HORÁRIO</th><th>SITUAÇÃO</th><th className="right">OPERAÇÃO</th></tr></thead><tbody>{rows.map(m=><tr key={m.id}><td><div className="fixture"><span>{playerById(c.state,m.home)?.nickname}</span><b>{m.status==='scheduled'?'×':`${m.homeScore} : ${m.awayScore}`}</b><span>{playerById(c.state,m.away)?.nickname}</span></div></td><td><Pill>{m.group}</Pill></td><td>{m.station}</td><td>{m.time}</td><td><Pill tone={['live','paused'].includes(m.status)?'green':m.status==='finished'?'amber':''}>{m.status==='live'?'Ao vivo':m.status==='paused'?'Pausada':m.status==='finished'?'A confirmar':m.status==='confirmed'?'Confirmada':'Agendada'}</Pill></td><td className="right"><Button onClick={()=>c.openMatch(m.id)}>{m.status==='confirmed'?'Ver resultado':'Operar'}<ArrowUpRight size={14}/></Button></td></tr>)}</tbody></table></div>{!rows.length&&<Empty title="Nenhuma partida nesta situação" detail="Selecione outra aba para continuar."/>}</div><div className="context-note"><FileCheck2 size={18}/><p>Apenas resultados confirmados entram na classificação e nos rankings oficiais.</p></div></>}

function MatchOperator(c:AppContext&{matchId:string;onClose:()=>void}){const m=c.state.matches.find(x=>x.id===c.matchId);const [confirmFinish,setConfirmFinish]=useState(false);if(!m)return null;const h=playerById(c.state,m.home),a=playerById(c.state,m.away);const locked=m.status==='confirmed';const canEvent=['live','paused'].includes(m.status);function change(fn:(m:Match)=>Match,msg:string){c.update(s=>({...s,matches:s.matches.map(x=>x.id===m!.id?fn(x):x)}),msg)}function add(type:'goal'|'yellow'|'red',side:'home'|'away'){const p=side==='home'?h:a;const ev={id:crypto.randomUUID(),type,side,name:p?.name||'',time:c.now,voided:false};change(x=>({...x,homeScore:x.homeScore+(type==='goal'&&side==='home'?1:0),awayScore:x.awayScore+(type==='goal'&&side==='away'?1:0),events:[ev,...x.events]}),`${type==='goal'?'Gol':type==='yellow'?'Cartão amarelo':'Cartão vermelho'}: ${p?.nickname}.`)}return <Modal title={`Operação da partida · Grupo ${m.group}`} onClose={c.onClose} wide><div className="operator-meta"><span>{m.station}</span><Pill tone={locked?'':'green'}>{locked?'Resultado confirmado':m.status==='finished'?'Aguardando confirmação':m.status==='scheduled'?'Pronta para começar':m.status==='paused'?'Pausada':'Ao vivo'}</Pill></div><div className="operator-score"><div><Club player={h} large/><h3>{h?.name}</h3><p>{h?.club}</p></div><div className="score-center"><strong>{m.homeScore}<span>:</span>{m.awayScore}</strong><span className="clock-display">{clock(m,c.now)}</span></div><div><Club player={a} large/><h3>{a?.name}</h3><p>{a?.club}</p></div></div><div className="operator-event-actions">{(['home','away'] as const).map(side=><div key={side}><Button disabled={!canEvent} kind="primary" onClick={()=>add('goal',side)}><Goal size={17}/>Gol de {side==='home'?h?.nickname:a?.nickname}</Button><div><Button disabled={!canEvent} title="Cartão amarelo" onClick={()=>add('yellow',side)}><span className="card-icon yellow"/>Amarelo</Button><Button disabled={!canEvent} title="Cartão vermelho" onClick={()=>add('red',side)}><span className="card-icon red"/>Vermelho</Button></div></div>)}</div><div className="operator-controls">{m.status==='scheduled'&&<Button kind="primary" onClick={()=>change(x=>({...x,status:'live',startedAt:Date.now()}),'Partida iniciada.')}><Play size={16}/>Iniciar partida</Button>}{m.status==='live'&&<Button onClick={()=>change(x=>({...x,status:'paused',elapsed:x.elapsed+(x.startedAt?Date.now()-x.startedAt:0),startedAt:null}),'Partida pausada.')}><Pause size={16}/>Pausar</Button>}{m.status==='paused'&&<Button kind="primary" onClick={()=>change(x=>({...x,status:'live',startedAt:Date.now()}),'Partida retomada.')}><Play size={16}/>Retomar</Button>}{canEvent&&!confirmFinish&&<Button onClick={()=>setConfirmFinish(true)}><Flag size={16}/>Encerrar partida</Button>}{confirmFinish&&canEvent&&<><span className="small-text">Encerrar com {m.homeScore} : {m.awayScore}?</span><Button kind="primary" onClick={()=>{change(x=>({...x,status:'finished',elapsed:x.elapsed+(x.startedAt?Date.now()-x.startedAt:0),startedAt:null}),'Partida encerrada. Confirme o resultado para oficializar.');setConfirmFinish(false)}}>Sim, encerrar</Button><Button onClick={()=>setConfirmFinish(false)}>Cancelar</Button></>}{m.status==='finished'&&<Button kind="primary" onClick={()=>change(x=>({...x,status:'confirmed'}),'Resultado confirmado. Classificação oficial atualizada.')}><CheckCheck size={16}/>Confirmar resultado</Button>}<Button onClick={()=>c.update(s=>({...s,selectedMatch:m.id,scene:'match'}),'Partida selecionada no Telão.')}><Monitor size={16}/>Enviar ao Telão</Button></div><div className="event-history"><h3>Acontecimentos da partida</h3>{m.events.length?m.events.map(ev=><div className={ev.voided?'voided':''} key={ev.id}><span>{ev.type==='goal'?<Goal size={16}/>:<span className={`card-icon ${ev.type}`}/>}</span><strong>{ev.type==='goal'?'Gol':ev.type==='yellow'?'Cartão amarelo':'Cartão vermelho'} · {ev.name}</strong><small>{ev.voided?'Anulado':new Date(ev.time).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small>{!locked&&!ev.voided&&<button title="Anular evento" className="icon-button" onClick={()=>change(x=>({...x,homeScore:Math.max(0,x.homeScore-(ev.type==='goal'&&ev.side==='home'?1:0)),awayScore:Math.max(0,x.awayScore-(ev.type==='goal'&&ev.side==='away'?1:0)),events:x.events.map(e=>e.id===ev.id?{...e,voided:true}:e)}),'Evento anulado. Placar corrigido.')}><RotateCcw size={15}/></button>}</div>):<p>Os novos eventos aparecerão aqui. O placar inicial faz parte da demonstração.</p>}</div></Modal>}

function Groups(c:AppContext){const [group,setGroup]=useState('A');return <><Heading title="A tabela conta a história." description="Acompanhe a disputa, os pontos e a caminhada de cada grupo."><Pill tone="green"><CheckCheck size={13}/>Resultados confirmados</Pill></Heading><div className="group-selector">{Array.from({length:c.state.settings.groupCount},(_,i)=>String.fromCharCode(65+i)).map(g=><button className={g===group?'selected':''} onClick={()=>setGroup(g)} key={g}><span>GRUPO</span><strong>{g}</strong><small>{c.state.players.filter(p=>p.group===g).length} jogadores</small></button>)}</div><section className="panel"><SectionTitle title={`Classificação · Grupo ${group}`} note="Fase de grupos · Turno único" action={<Trophy size={22} className="accent-text"/>}/><StandingsTable {...c} group={group}/><div className="panel-foot">PTS pontos · J jogos · V vitórias · E empates · D derrotas · GP gols pró · GC gols contra · SG saldo de gols</div></section><div className="context-note amber-note"><Shield size={18}/><p>O critério de avanço às oitavas ainda precisa ser definido no regulamento. A interface não presume os classificados.</p></div></>}
function Rankings(c:AppContext){const [category,setCategory]=useState('goals');const [mvp,setMvp]=useState('');const [reason,setReason]=useState('');const [nomination,setNomination]=useState('');const confirmed=c.state.matches.filter(m=>m.status==='confirmed');const entries=c.state.players.filter(p=>p.status==='approved').map(p=>{const games=confirmed.filter(m=>m.home===p.id||m.away===p.id);const goals=games.reduce((n,m)=>n+(m.home===p.id?m.homeScore:m.awayScore),0);const cards=games.reduce((n,m)=>n+m.events.filter(e=>e.type!=='goal'&&!e.voided&&e.name===p.name).length,0);return {...p,goals,cards,played:games.length}}).filter(p=>p.played>0).sort((a,b)=>category==='cards'?b.cards-a.cards:b.goals-a.goals);return <><Heading title="Quem está escrevendo seu nome?" description="Destaques e conquistas que vão ficar na memória da nossa liga."><Pill>Estatísticas oficiais</Pill></Heading><div className="ranking-tabs"><button className={category==='goals'?'selected':''} onClick={()=>setCategory('goals')}><Goal size={19}/>Artilharia</button><button className={category==='cards'?'selected':''} onClick={()=>setCategory('cards')}><Shield size={19}/>Disciplina</button><button className={category==='mvp'?'selected':''} onClick={()=>setCategory('mvp')}><Sparkles size={19}/>Melhor jogador</button></div>{category==='mvp'?<section className="panel mvp-panel"><Trophy size={44}/><h2>O craque vai além do placar.</h2><p>Seleção da organização, acompanhada de justificativa.</p><form onSubmit={e=>{e.preventDefault();setNomination(mvp);c.notify('Indicação de MVP registrada nesta sessão de demonstração.')}}><label className="field">Jogador<select required value={mvp} onChange={e=>setMvp(e.target.value)}><option value="">Selecione o participante</option>{c.state.players.filter(p=>p.status==='approved').map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label className="field">Justificativa<textarea required minLength={10} value={reason} onChange={e=>setReason(e.target.value)}/></label><Button type="submit" kind="primary"><Trophy size={16}/>Registrar indicação</Button></form>{nomination&&<Pill tone="green">Indicado: {playerById(c.state,nomination)?.name}</Pill>}</section>:<div className="panel"><SectionTitle title={category==='goals'?'Corrida pela artilharia':'Disciplina da competição'} note={category==='goals'?'Gols por participante humano · Apenas partidas confirmadas':'Cartões registrados em partidas confirmadas'}/><div className="table-scroll"><table><thead><tr><th>POSIÇÃO</th><th>JOGADOR</th><th>CLUBE</th><th>JOGOS</th><th>{category==='cards'?'CARTÕES':'GOLS'}</th></tr></thead><tbody>{entries.map((p,i)=><tr key={p.id}><td><span className={`ranking-position ${i===0?'first':''}`}>{i===0?<Trophy size={18}/>:String(i+1).padStart(2,'0')}</span></td><td><div className="table-player"><Avatar player={p}/><strong>{p.name}</strong></div></td><td>{p.club}</td><td>{p.played}</td><td className="ranking-number">{category==='cards'?p.cards:p.goals}</td></tr>)}</tbody></table></div></div>}</>}

function LiveControl(c:AppContext){const selected=c.state.matches.find(m=>m.id===c.state.selectedMatch)||c.state.matches[0];const scenes=[['match','Partida atual',Gamepad2],['groups','Classificação',LayoutGrid],['opening','Abertura',Trophy]] as const;return <><Heading eyebrow="ARENA MARKS LIVE" title="A resenha ganha a tela grande." description="Escolha a partida e a cena que o público vai acompanhar."><Link className="button primary" href="/live" target="_blank"><Expand size={16}/>Abrir Telão<ArrowUpRight size={14}/></Link></Heading><div className="live-control-layout"><section><div className="live-preview"><LiveScene {...c}/></div><div className="preview-caption"><span><i className="online-dot"/>Prévia do Telão</span><span>16:9 · Sincronização local entre abas</span></div></section><section className="panel live-settings"><SectionTitle title="Direção de arena"/><label className="field">Partida principal<select value={selected.id} onChange={e=>c.update(s=>({...s,selectedMatch:e.target.value}),'Partida principal do Telão atualizada.')}>{c.state.matches.map(m=><option key={m.id} value={m.id}>{playerById(c.state,m.home)?.nickname} × {playerById(c.state,m.away)?.nickname} · {m.station}</option>)}</select></label><div className="field"><span>Cena em exibição</span><div className="scene-buttons">{scenes.map(([v,label,Icon])=><button className={c.state.scene===v?'selected':''} onClick={()=>c.update(s=>({...s,scene:v}),`Cena do Telão: ${label}.`)} key={v}><Icon size={19}/>{label}{c.state.scene===v&&<Check size={17}/>}</button>)}</div></div><Button className="full-width" onClick={()=>c.openMatch(selected.id)}><Gamepad2 size={16}/>Operar partida selecionada</Button></section></div><div className="context-note"><Wifi size={18}/><p>Nesta V1, o Telão acompanha alterações em abas do mesmo navegador e endereço. A conexão entre dispositivos via WebSocket será integrada ao backend.</p></div></>}
function LiveScene(c:AppContext){return <ReferenceLive {...c} compact/>}
function LiveScreen(c:AppContext&{overlay:boolean}){const path=usePathname();return <ReferenceLive {...c} overlay={c.overlay?(path?.split('/').pop()||'match'):undefined}/>}
function Broadcast(c:AppContext){const [origin,setOrigin]=useState('');useEffect(()=>setOrigin(location.origin),[]);return <><Heading eyebrow="ARENA MARKS BROADCAST" title="A liga também vai para a transmissão." description="Fontes independentes para compor a apresentação no OBS."><Pill>Primeira versão visual</Pill></Heading><div className="broadcast-grid">{[{title:'Placar da partida',detail:'Placar e jogadores sobre fundo transparente.',scene:'score',icon:Gamepad2},{title:'Partida completa',detail:'Cena da arena com os participantes e cronômetro.',scene:'match',icon:Monitor},{title:'Classificação',detail:'Tabela oficial do grupo da partida selecionada.',scene:'groups',icon:LayoutGrid}].map(item=><article className="panel broadcast-card" key={item.scene}><item.icon size={25}/><h2>{item.title}</h2><p>{item.detail}</p><div className="overlay-mini"><Shield size={30}/><strong>ARENA MARKS</strong><span>{item.title.toUpperCase()}</span></div><label className="field">URL da fonte<input readOnly value={`${origin}/overlay/${item.scene}`}/></label><div className="broadcast-actions"><Button onClick={()=>navigator.clipboard.writeText(`${origin}/overlay/${item.scene}`).then(()=>c.notify('Link da fonte copiado.')).catch(()=>c.notify('Copie o endereço no campo da fonte.'))}><Copy size={14}/>Copiar</Button><Link className="button" href={`/overlay/${item.scene}`} target="_blank">Visualizar<ArrowUpRight size={14}/></Link></div></article>)}</div><div className="context-note amber-note"><Radio size={18}/><p>Fontes visuais desta prévia usam os dados locais do navegador. A sincronização com o navegador interno do OBS depende da API e não está ativa nesta V1.</p></div></>}

function SettingsPage(c:AppContext){const [settings,setSettings]=useState(c.state.settings);return <><Heading title="Uma edição com a nossa cara." description="Parâmetros da competição, identidade e operação da arena."/><form className="settings-form" onSubmit={e=>{e.preventDefault();c.update(s=>({...s,settings}),'Configurações da edição salvas.')}}><section className="panel"><SectionTitle title="Identidade da edição" note="Informações apresentadas no portal e na arena"/><div className="form-grid"><label className="field full">Nome da edição<input required value={settings.title} onChange={e=>setSettings({...settings,title:e.target.value})}/></label><label className="field">Jogo<input required value={settings.game} onChange={e=>setSettings({...settings,game:e.target.value})}/></label><label className="field">Data do evento<input type="date" value={settings.date} onChange={e=>setSettings({...settings,date:e.target.value})}/></label><label className="field">Horário do evento<input type="time" value={settings.time??''} onChange={e=>setSettings({...settings,time:e.target.value})}/></label><label className="field full">Local do evento<input maxLength={160} value={settings.venue??''} onChange={e=>setSettings({...settings,venue:e.target.value})}/></label><label className="field full">Regulamento do portal<textarea rows={8} maxLength={12000} value={settings.rules??''} onChange={e=>setSettings({...settings,rules:e.target.value})}/></label></div></section><section className="panel"><SectionTitle title="Estrutura e pontuação" note="Parâmetros configuráveis por edição"/><div className="form-grid">{[{key:'capacity',label:'Vagas de participantes',min:Math.max(2,c.state.players.filter(p=>p.status!=='rejected').length),max:128},{key:'groupCount',label:'Quantidade de grupos',min:1,max:16},{key:'stationCount',label:'Estações disponíveis',min:1,max:12},{key:'winPoints',label:'Pontos por vitória',min:1,max:10},{key:'drawPoints',label:'Pontos por empate',min:0,max:10}].map(f=><label className="field" key={f.key}>{f.label}<input type="number" required min={f.min} max={f.max} value={settings[f.key as keyof typeof settings]} onChange={e=>setSettings({...settings,[f.key]:Number(e.target.value)})}/></label>)}</div></section><div className="settings-save"><span>Alterações salvas apenas neste navegador nesta V1.</span><Button kind="primary" type="submit"><Check size={16}/>Salvar configurações</Button></div></form></>}

function PublicPortal(c:AppContext&{registration:boolean}){const [success,setSuccess]=useState('');const [photo,setPhoto]=useState('');const [error,setError]=useState('');const [terms,setTerms]=useState(false);const [viewRules,setViewRules]=useState(false);const available=Math.max(0,c.state.settings.capacity-c.state.players.filter(p=>p.status!=='rejected').length);function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);if(!terms||!photo){setError('Adicione sua fotografia e aceite os termos da inscrição.');return}if(available<=0){setError('As vagas desta edição estão preenchidas.');return}const name=String(form.get('name')||'').trim(),contact=String(form.get('contact')||'').trim();if(c.state.players.some(p=>p.contact&&p.contact.toLowerCase()===contact.toLowerCase()&&p.status!=='rejected')){setError('Já existe uma inscrição com este contato.');return}const id=crypto.randomUUID();c.update(s=>({...s,players:[...s.players,{id,name,nickname:String(form.get('nickname')||name.split(' ')[0]),club:'',photo,status:'pending',color:'#a6d38e',group:'',contact}]}),'Inscrição recebida para análise.');setSuccess(id.slice(0,8).toUpperCase())}return <div className="public-page"><header className="public-header"><Link className="brand" href="/portal"><img src="/arena-marks.png" alt=""/><div>ARENA <b>MARKS</b><small>CHAMPIONS START HERE</small></div></Link><nav><Link href="/portal">O campeonato</Link><button onClick={()=>setViewRules(true)}>Regulamento</button><Link href="/grupos">Classificação</Link></nav><Link className="button" href="/"><LayoutDashboard size={15}/>Organização</Link></header>{c.registration?<main className="registration-layout"><div className="registration-intro"><Link className="text-link" href="/portal"><ArrowLeft size={15}/>Voltar ao campeonato</Link><div className="eyebrow">CHAMPIONS MARKS LEAGUE II</div><h1>A próxima história<br/>pode ser a sua.</h1><p>Inscreva-se para viver o campeonato com a gente.</p><img src="/stadium.jpg" alt="Campo de futebol em um estádio"/><div className="context-note"><Shield size={19}/><p>As inscrições são analisadas pela organização antes do sorteio.</p></div></div><section className="panel registration-form"><SectionTitle title="Entre para a nossa liga" note="Seus dados de contato são privados."/>{success?<div className="registration-success"><CheckCheck size={45}/><h2>Você deu o primeiro passo!</h2><p>Inscrição enviada. Agora é com a organização.</p><strong>PROTOCOLO {success}</strong><Pill tone="amber">Em análise</Pill><Link className="button" href="/portal">Voltar ao campeonato<ArrowRight size={15}/></Link></div>:<form onSubmit={submit}><div className="form-grid"><label className="field full">Nome completo<input name="name" required maxLength={80} placeholder="Como você se chama?"/></label><label className="field full">Apelido<input name="nickname" maxLength={30} placeholder="Como a resenha conhece você?"/></label><label className="field full">E-mail para contato<input name="contact" type="email" required maxLength={120} placeholder="voce@exemplo.com"/></label><ImageUpload value={photo} onChange={setPhoto} onError={setError}/></div><label className="checkbox-label"><input type="checkbox" checked={terms} onChange={e=>setTerms(e.target.checked)} required/><span>Li o regulamento e autorizo o uso do meu nome e foto nesta demonstração do campeonato.</span></label>{available<=0&&<div className="context-note amber-note"><Users size={18}/><p>As {c.state.settings.capacity} vagas da edição de demonstração estão ocupadas. A organização pode ajustar a capacidade.</p></div>}{error&&<p className="form-error">{error}</p>}<Button className="full-width" kind="primary" type="submit" disabled={available<=0}>Enviar minha inscrição<ArrowRight size={16}/></Button><p className="registration-disclaimer">Prévia local. Seus dados ficam neste navegador.</p></form>}</section></main>:<><section className="public-hero" style={{backgroundImage:'linear-gradient(90deg,rgba(6,10,8,.91),rgba(6,10,8,.28)),url(/stadium.jpg)'}}><div className="public-hero-inner"><div className="eyebrow"><i className="online-dot"/>A NOSSA RESENHA. A NOSSA LIGA.</div><h1>CHAMPIONS<br/>MARKS LEAGUE <span>II</span></h1><p>O jogo é virtual.<br/>As histórias são de verdade.</p><div className="public-hero-actions"><Link href="/inscrever" className="button primary">Quero entrar em campo<ArrowUpRight size={17}/></Link><button className="hero-rule-link" onClick={()=>setViewRules(true)}>Conheça o regulamento<ArrowRight size={16}/></button></div><div className="public-hero-meta"><span><Gamepad2 size={16}/>{c.state.settings.game}</span><span><Users size={16}/>{c.state.settings.capacity} protagonistas</span><span><Clock3 size={16}/>Data a definir</span></div></div><span className="hero-edition">II EDIÇÃO <b>2026</b></span></section><section className="public-bottom"><div><div className="eyebrow">MAIS QUE UMA COMPETIÇÃO</div><h2>Da sala de casa<br/>para a nossa arena.</h2><p>Família reunida, controle na mão e aquela resenha que continua depois do apito final.</p></div><div className="public-facts"><article><Trophy size={25}/><strong>Uma liga.<br/>Muitas histórias.</strong><p>Grupos, mata-mata e a caminhada até a taça.</p></article><article><Users size={25}/><strong>Entre amigos.<br/>Com respeito.</strong><p>Competição de verdade, convivência em primeiro lugar.</p></article><article><Monitor size={25}/><strong>Cada lance.<br/>Na tela grande.</strong><p>Placar, partidas e a emoção do campeonato ao vivo.</p></article></div></section></>}{viewRules&&<Modal title="Regulamento · Primeira versão" onClose={()=>setViewRules(false)}><div className="rules-copy"><p>Formato individual · {c.state.settings.game} · {c.state.settings.capacity} vagas planejadas.</p><p>Vitória: {c.state.settings.winPoints} pontos. Empate: {c.state.settings.drawPoints} ponto(s). Derrota: 0.</p><p>Inscrições passam por análise. Apenas participantes aprovados entram no sorteio.</p><p>Critérios finais de avanço, desempate, suspensões e data do evento serão publicados pela organização antes da competição oficial.</p><p>Respeito entre participantes, organização e público é condição de participação.</p></div><div className="modal-actions"><Button onClick={()=>setViewRules(false)}>Entendi</Button></div></Modal>}<footer className="public-footer"><strong>ARENA MARKS</strong><span>A nossa resenha. A nossa liga.</span><small>Demonstração V1 · 2026</small></footer></div>}
